# backup.sh — the install-migration `backup <file>` helper, sourced by install.sh and by the
# migration test harness (deploy/migrations/lib/test-harness.sh) so both run the same code.
#
# backup <file>  copies <file> into $BACKUP_DIR (overwriting a same-named file) and prints
#                `    backup: $BACKUP_DIR/<name>`; a missing <file> is a no-op.
# >>> shguard modes=source (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'scripts/lib/backup.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  source) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: source; pipe callers set SHGUARD_MODE=pipe)\n' 'backup.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
backup() {
  local f=$1
  [[ -e $f ]] || return 0
  mkdir -p "$BACKUP_DIR"
  cp -p -- "$f" "$BACKUP_DIR/$(basename "$f")"
  echo "    backup: $BACKUP_DIR/$(basename "$f")"
}
